import type { RequestHandler } from "@builder.io/qwik-city";
import { mockRedis } from "../../../mock-redis-store";

/**
 * GET /api/debug-store
 * Returns the current state of the in-memory mock Redis store.
 */
export const onGet: RequestHandler = (ev) => {
  ev.json(200, { keys: mockRedis.getAll() });
};

/**
 * In-memory mock Redis-like key-value store.
 * Used for rate limiting — tracks request counts per IP per time window.
 */
class MockRedisStore {
  private store: Map<string, number> = new Map();

  /**
   * Increment the value for a given key. Returns the new value.
   * If the key does not exist, it is set to 1.
   */
  incr(key: string): number {
    const current = this.store.get(key) ?? 0;
    const next = current + 1;
    this.store.set(key, next);
    return next;
  }

  /**
   * Get the current value for a key (or 0 if not set).
   */
  get(key: string): number {
    return this.store.get(key) ?? 0;
  }

  /**
   * Remove expired keys — those whose window ID is less than the current window.
   * The key format is expected to be `ratelimit:<ip>:<windowId>`.
   */
  cleanupExpired(currentWindowId: number): void {
    for (const key of this.store.keys()) {
      const parts = key.split(":");
      if (parts.length === 3) {
        const windowId = parseInt(parts[2], 10);
        if (!isNaN(windowId) && windowId < currentWindowId) {
          this.store.delete(key);
        }
      }
    }
  }

  /**
   * Return a snapshot of all keys and their values.
   */
  getAll(): Record<string, number> {
    const result: Record<string, number> = {};
    for (const [key, value] of this.store.entries()) {
      result[key] = value;
    }
    return result;
  }
}

/** Singleton instance shared across all requests. */
export const mockRedis = new MockRedisStore();

import type { RequestHandler } from "@builder.io/qwik-city";
import { mockRedis } from "../mock-redis-store";

const RATE_LIMIT = 5;
const WINDOW_SECONDS = 10;

/**
 * Server plugin — runs as middleware before every request.
 * Applies rate limiting to the `/api/data` endpoint.
 */
export const onRequest: RequestHandler = (ev) => {
  // Only apply rate limiting to /api/data
  if (ev.pathname !== "/api/data") {
    return;
  }

  const now = Date.now();
  const windowId = Math.floor(now / (WINDOW_SECONDS * 1000));
  const resetTimestamp = (windowId + 1) * WINDOW_SECONDS;

  // Determine client IP
  const xForwardedFor = ev.request.headers.get("X-Forwarded-For");
  let clientIp: string;
  if (xForwardedFor) {
    // Take the first IP in the X-Forwarded-For list
    clientIp = xForwardedFor.split(",")[0].trim();
  } else if (ev.clientConn.ip) {
    clientIp = ev.clientConn.ip;
  } else {
    clientIp = "127.0.0.1";
  }

  // Clean up expired keys
  mockRedis.cleanupExpired(windowId);

  // Build the rate-limit key
  const key = `ratelimit:${clientIp}:${windowId}`;

  // Increment the counter
  const currentCount = mockRedis.incr(key);

  // Calculate remaining
  const remaining = Math.max(0, RATE_LIMIT - currentCount);

  // Set rate-limit headers on every response
  ev.headers.set("X-RateLimit-Limit", String(RATE_LIMIT));
  ev.headers.set("X-RateLimit-Remaining", String(remaining));
  ev.headers.set("X-RateLimit-Reset", String(resetTimestamp));

  // If over the limit, block the request
  if (currentCount > RATE_LIMIT) {
    // Ensure remaining is 0 for rate-limited responses
    ev.headers.set("X-RateLimit-Remaining", "0");
    throw ev.json(429, { error: "Too Many Requests" });
  }
};

import type { RequestHandler } from "@builder.io/qwik-city";

/**
 * GET /api/data
 * Returns a simple success response.
 * Rate limiting is handled by the server plugin (plugin.ts).
 */
export const onGet: RequestHandler = (ev) => {
  ev.json(200, { data: "Success" });
};
